from pathlib import Path

page_path = Path("app/teacher/reports/page.tsx")
audit_path = Path("scripts/runtime-audit.mjs")
route_path = Path("app/api/teacher/attendance-report/route.ts")

page = page_path.read_text(encoding="utf-8")

old_imports = '''import { collection, onSnapshot, query, where } from "firebase/firestore";\nimport { db } from "../../../lib/firebase";\nimport { tenantCollection } from "../../../lib/teacher-tenant";\n'''
if old_imports in page:
    page = page.replace(old_imports, "", 1)

old_effect = '''  useEffect(() => {\n    if (!teacherId || !subjectKey || reportType !== "attendance") {\n      setAttendanceDocs([]);\n      return;\n    }\n    const base = collection(db, tenantCollection(teacherId, subjectKey as never, "attendance"));\n    const scopedQuery = attendanceMode === "daily"\n      ? query(base, where("date", "==", selectedDate))\n      : query(base, where("date", ">=", reportFrom), where("date", "<=", reportTo));\n    return onSnapshot(\n      scopedQuery,\n      snapshot => setAttendanceDocs(snapshot.docs.map(item => item.data() as AttendanceDoc)),\n      () => setAttendanceDocs([]),\n    );\n  }, [teacherId, subjectKey, reportType, attendanceMode, selectedDate, reportFrom, reportTo]);\n'''
new_effect = '''  useEffect(() => {\n    if (!teacherId || !subjectKey || reportType !== "attendance") {\n      setAttendanceDocs([]);\n      return;\n    }\n    const controller = new AbortController();\n    const params = new URLSearchParams({ subjectId: subjectKey, mode: attendanceMode });\n    if (attendanceMode === "daily") params.set("date", selectedDate);\n    else {\n      params.set("from", reportFrom);\n      params.set("to", reportTo);\n    }\n    fetch(`/api/teacher/attendance-report?${params.toString()}`, { cache: "no-store", signal: controller.signal })\n      .then(async response => {\n        const data = await response.json().catch(() => ({}));\n        if (!response.ok) throw new Error(data.message || "تعذر تحميل سجل الحضور");\n        return data;\n      })\n      .then(data => setAttendanceDocs(Array.isArray(data.attendance) ? data.attendance : []))\n      .catch(error => {\n        if ((error as Error)?.name !== "AbortError") setAttendanceDocs([]);\n      });\n    return () => controller.abort();\n  }, [teacherId, subjectKey, reportType, attendanceMode, selectedDate, reportFrom, reportTo]);\n'''
if old_effect in page:
    page = page.replace(old_effect, new_effect, 1)
elif "/api/teacher/attendance-report" not in page:
    raise SystemExit("reports attendance effect did not match expected source")

page_path.write_text(page, encoding="utf-8")

route_path.parent.mkdir(parents=True, exist_ok=True)
route_path.write_text('''import { NextResponse } from "next/server";\nimport { adminDb } from "../../../../lib/server/firebase-admin";\nimport { requireSession } from "../../../../lib/server/portal-auth";\nimport { normalizeAssignments } from "../../../../lib/teacher-assignments";\nimport { isSubjectKey } from "../../../../lib/subject-config";\n\nconst DATE_PATTERN = /^\\d{4}-\\d{2}-\\d{2}$/;\nconst DAY_MS = 86_400_000;\n\nfunction validDate(value: string) {\n  return DATE_PATTERN.test(value) && !Number.isNaN(Date.parse(`${value}T12:00:00Z`));\n}\n\nfunction inclusiveDays(from: string, to: string) {\n  return Math.floor((Date.parse(`${to}T12:00:00Z`) - Date.parse(`${from}T12:00:00Z`)) / DAY_MS) + 1;\n}\n\nexport async function GET(request: Request) {\n  const session = await requireSession("teacher");\n  if (!session?.user) {\n    return NextResponse.json({ ok: false, message: "انتهت جلسة المعلم." }, { status: 401 });\n  }\n\n  const url = new URL(request.url);\n  const subjectId = String(url.searchParams.get("subjectId") || "").split("--")[0];\n  const mode = url.searchParams.get("mode") === "daily" ? "daily" : "range";\n  if (!isSubjectKey(subjectId)) {\n    return NextResponse.json({ ok: false, message: "المادة غير صحيحة." }, { status: 400 });\n  }\n\n  const assignments = normalizeAssignments(session.user.assignments, session.user.subjectIds);\n  if (!assignments.some(item => item.subjectId === subjectId)) {\n    return NextResponse.json({ ok: false, message: "المادة غير مسندة إلى الحساب." }, { status: 403 });\n  }\n\n  const collection = adminDb().collection(`portalV2Data/${session.userId}/subjects/${subjectId}/attendance`);\n  let query: FirebaseFirestore.Query = collection;\n\n  if (mode === "daily") {\n    const date = String(url.searchParams.get("date") || "");\n    if (!validDate(date)) {\n      return NextResponse.json({ ok: false, message: "تاريخ التقرير غير صحيح." }, { status: 400 });\n    }\n    query = collection.where("date", "==", date);\n  } else {\n    const from = String(url.searchParams.get("from") || "");\n    const to = String(url.searchParams.get("to") || "");\n    if (!validDate(from) || !validDate(to) || from > to || inclusiveDays(from, to) > 31) {\n      return NextResponse.json({ ok: false, message: "فترة التقرير غير صحيحة أو تتجاوز 31 يومًا." }, { status: 400 });\n    }\n    query = collection.where("date", ">=", from).where("date", "<=", to);\n  }\n\n  try {\n    const snapshot = await query.get();\n    const attendance = snapshot.docs.map(document => ({\n      id: document.id,\n      ...(document.data() as Record<string, unknown>),\n    }));\n    return NextResponse.json(\n      { ok: true, attendance },\n      { headers: { "Cache-Control": "private, no-store, max-age=0" } },\n    );\n  } catch (error) {\n    console.error("teacher attendance report read failed", error);\n    return NextResponse.json(\n      { ok: false, attendance: [], message: "تعذر تحميل سجل الحضور الآن." },\n      { status: 503, headers: { "Cache-Control": "no-store" } },\n    );\n  }\n}\n''', encoding="utf-8")

audit = audit_path.read_text(encoding="utf-8")
old_audit = '''// حماية التقارير: القراءة يجب أن تكون حسب اليوم أو الفترة المختارة فقط.\nrequirePattern(\n  "app/teacher/reports/page.tsx",\n  /where\\(\\s*["']date["']\\s*,\\s*["']==["']\\s*,\\s*selectedDate\\s*\\)/,\n  "التقرير اليومي يجب أن يقرأ التاريخ المختار فقط.",\n);\nrequirePattern(\n  "app/teacher/reports/page.tsx",\n  /where\\(\\s*["']date["']\\s*,\\s*["']>=["']\\s*,\\s*reportFrom\\s*\\)/,\n  "تقرير الفترة يجب أن يبدأ من التاريخ المختار بدل قراءة الأرشيف كاملًا.",\n);\nrequirePattern(\n  "app/teacher/reports/page.tsx",\n  /where\\(\\s*["']date["']\\s*,\\s*["']<=["']\\s*,\\s*reportTo\\s*\\)/,\n  "تقرير الفترة يجب أن ينتهي عند التاريخ المختار بدل قراءة الأرشيف كاملًا.",\n);\nforbid(\n  "app/teacher/reports/page.tsx",\n  /onSnapshot\\(\\s*collection\\([^\\n]*["']attendance["']/,\n  "الاستماع إلى كل سجل الحضور من صفحة التقارير ممنوع.",\n);\n'''
new_audit = '''// حماية التقارير: لا قراءة Firestore مباشرة من المتصفح؛ طلب خادمي واحد محدود باليوم أو 31 يومًا.\nforbid(\n  "app/teacher/reports/page.tsx",\n  /firebase\\/firestore|\\bonSnapshot\\s*\\(|\\bgetDocs\\s*\\(|\\bcollection\\s*\\(/,\n  "صفحة التقارير يجب ألا تقرأ Firestore مباشرة من المتصفح.",\n);\nrequirePattern(\n  "app/teacher/reports/page.tsx",\n  /\\/api\\/teacher\\/attendance-report/,\n  "صفحة التقارير يجب أن تستخدم API الحضور الخادمي المحدود.",\n);\nrequirePattern(\n  "app/api/teacher/attendance-report/route.ts",\n  /where\\(\\s*["']date["']\\s*,\\s*["']==["']/,\n  "API التقرير اليومي يجب أن يقيد القراءة بتاريخ واحد.",\n);\nrequirePattern(\n  "app/api/teacher/attendance-report/route.ts",\n  /where\\(\\s*["']date["']\\s*,\\s*["']>=["']/,\n  "API تقرير الفترة يجب أن يبدأ من التاريخ المختار.",\n);\nrequirePattern(\n  "app/api/teacher/attendance-report/route.ts",\n  /where\\(\\s*["']date["']\\s*,\\s*["']<=["']/,\n  "API تقرير الفترة يجب أن ينتهي عند التاريخ المختار.",\n);\nrequirePattern(\n  "app/api/teacher/attendance-report/route.ts",\n  /inclusiveDays\\(from, to\\) > 31/,\n  "API تقرير الفترة يجب أن يمنع قراءة أكثر من 31 يومًا.",\n);\n'''
if old_audit in audit:
    audit = audit.replace(old_audit, new_audit, 1)
elif "attendance-report/route.ts" not in audit:
    raise SystemExit("runtime audit reports block did not match expected source")

audit_path.write_text(audit, encoding="utf-8")
